package com.quincaisoft.company.infrastructure;import jakarta.persistence.*;import java.util.*;@Entity @Table(name="company") @IdClass(CompanyEntity.Key.class) public class CompanyEntity {public record Key(UUID tenantId,UUID id) implements java.io.Serializable{}@Id @Column(name="tenant_id")public UUID tenantId;@Id public UUID id;public String name;@Column(name="branch_count") public long branchCount;}